@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

@keyframes pulse-soft {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.35);
  }
}

@keyframes float-slow {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

@keyframes scan {
  0% {
    transform: translateY(-100%);
  }
  100% {
    transform: translateY(1000%);
  }
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.15;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slide-in {
  from {
    opacity: 0;
    transform: translateX(18px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes dash {
  to {
    stroke-dashoffset: -24;
  }
}

.animate-marquee {
  animation: marquee 48s linear infinite;
}

.animate-pulse-soft {
  animation: pulse-soft 2.4s ease-in-out infinite;
}

.animate-float {
  animation: float-slow 7s ease-in-out infinite;
}

.animate-scan {
  animation: scan 8s linear infinite;
}

.animate-blink {
  animation: blink 1.8s ease-in-out infinite;
}

.animate-rise {
  animation: rise 420ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.animate-slide-in {
  animation: slide-in 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.animate-dash {
  stroke-dasharray: 6 6;
  animation: dash 1.4s linear infinite;
}

.scrollbar-none {
  scrollbar-width: none;
}

.scrollbar-none::-webkit-scrollbar {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

'use client'

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import type { ActionResult, GameState, Toast } from '@/lib/types'
import { createInitialState, SAVE_VERSION } from '@/lib/seed'
import { advance, applyWorldEvent } from '@/lib/simulation'
import { checkEngine, requestWorldEvent } from '@/lib/grok'

const SAVE_KEY = 'omnilife.syndicate.save.v7'
const TICK_MS = 3000

interface GameContextValue {
  state: GameState
  toasts: Toast[]
  hydrated: boolean
  paused: boolean
  speed: number
  engineOnline: boolean
  setPaused: (value: boolean) => void
  setSpeed: (value: number) => void
  dismissToast: (id: string) => void
  runAction: (action: (state: GameState) => ActionResult) => void
  pushToast: (toast: Omit<Toast, 'id'>) => void
  resetWorld: () => void
}

const GameContext = createContext<GameContextValue | null>(null)

export function GameProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<GameState>(() => createInitialState())
  const [toasts, setToasts] = useState<Toast[]>([])
  const [hydrated, setHydrated] = useState(false)
  const [paused, setPaused] = useState(false)
  const [speed, setSpeed] = useState(1)
  const [engineOnline, setEngineOnline] = useState(false)
  const stateRef = useRef(state)
  const syncRef = useRef(0)
  const toastTimers = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map())

  useEffect(() => {
    stateRef.current = state
  }, [state])

  const dismissToast = useCallback((id: string) => {
    setToasts((current) => current.filter((toast) => toast.id !== id))
    const timer = toastTimers.current.get(id)
    if (timer) clearTimeout(timer)
    toastTimers.current.delete(id)
  }, [])

  const pushToast = useCallback(
    (toast: Omit<Toast, 'id'>) => {
      const id = `toast_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`
      setToasts((current) => [...current.slice(-4), { ...toast, id }])
      const timer = setTimeout(() => dismissToast(id), 6200)
      toastTimers.current.set(id, timer)
    },
    [dismissToast],
  )

  const runAction = useCallback(
    (action: (current: GameState) => ActionResult) => {
      const result = action(stateRef.current)
      stateRef.current = result.state
      setState(result.state)
      if (result.toast) pushToast(result.toast)
    },
    [pushToast],
  )

  useEffect(() => {
    try {
      const saved = window.localStorage.getItem(SAVE_KEY)
      if (saved) {
        const parsed = JSON.parse(saved) as GameState
        if (parsed?.version === SAVE_VERSION && parsed.player && parsed.tokens) {
          stateRef.current = parsed
          setState(parsed)
        }
      }
    } catch {
      // A corrupt save should never prevent the world from booting.
    }
    setHydrated(true)
  }, [])

  useEffect(() => {
    if (!hydrated) return
    const timer = setTimeout(() => {
      try {
        window.localStorage.setItem(SAVE_KEY, JSON.stringify(state))
      } catch {
        // Storage quota is not a simulation failure.
      }
    }, 500)
    return () => clearTimeout(timer)
  }, [state, hydrated])

  useEffect(() => {
    if (paused) return
    const interval = setInterval(() => {
      setState((current) => advance(current))
    }, TICK_MS / speed)
    return () => clearInterval(interval)
  }, [paused, speed])

  useEffect(() => {
    let cancelled = false
    checkEngine().then((result) => {
      if (cancelled) return
      setEngineOnline(result.source === 'grok')
      setState((current) => ({
        ...current,
        engineStatus: result.source === 'grok' ? 'grok' : 'local',
      }))
    })
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    const interval = setInterval(() => {
      const current = stateRef.current
      if (current.tick - syncRef.current < 10) return
      syncRef.current = current.tick
      requestWorldEvent(current).then((event) => {
        if (!event) return
        setState((prev) => {
          const next = applyWorldEvent(prev, event)
          stateRef.current = next
          return next
        })
      })
    }, 18_000)
    return () => clearInterval(interval)
  }, [])

  const resetWorld = useCallback(() => {
    const fresh = createInitialState()
    stateRef.current = fresh
    setState(fresh)
    try {
      window.localStorage.removeItem(SAVE_KEY)
    } catch {
      // ignore
    }
    pushToast({ title: 'WORLD RESEEDED', message: 'A fresh simulation is now running.', tone: 'info' })
  }, [pushToast])

  const value = useMemo<GameContextValue>(
    () => ({
      state,
      toasts,
      hydrated,
      paused,
      speed,
      engineOnline,
      setPaused,
      setSpeed,
      dismissToast,
      runAction,
      pushToast,
      resetWorld,
    }),
    [state, toasts, hydrated, paused, speed, engineOnline, dismissToast, runAction, pushToast, resetWorld],
  )

  return <GameContext.Provider value={value}>{children}</GameContext.Provider>
}

export function useGame(): GameContextValue {
  const context = useContext(GameContext)
  if (!context) throw new Error('useGame must be used inside GameProvider')
  return context
}

