81: export function allocation(state: GameState) {
82:   const isps = state.isps.filter((isp) => isp.playerOwned).reduce((total, isp) => total + ispValue(isp), 0)
83:   const stations = state.media.filter((station) => station.playerOwned).reduce((total, station) => total + mediaValue(station), 0)
84:   const banks = state.banks.filter((bank) => bank.playerOwned).reduce((total, bank) => total + bankEquity(bank) * 0.35, 0)
85:   const corps = state.corporations.reduce((total, corp) => total + corporationValue(corp), 0)
86:   const tokens = portfolioValue(state)
87:   const property = districtValue(state)
88:   const cash = state.player.cash + state.player.legalFund
89:   return [
90:     { label: 'Liquid cash', value: cash, hue: 174 },
91:     { label: 'Token book', value: tokens, hue: 286 },
92:     { label: 'Infrastructure', value: isps, hue: 196 },
93:     { label: 'Media reach', value: stations, hue: 302 },
94:     { label: 'Equities', value: corps, hue: 42 },
95:     { label: 'Banking', value: banks, hue: 218 },
96:     { label: 'District deeds', value: property, hue: 142 },
97:   ].filter((item) => item.value > 0)
98: }
