100: export function dailyIncome(state: GameState): number {
101:   const isp = state.isps.filter((item) => item.playerOwned).reduce((total, item) => total + item.revenue, 0)
102:   const media = state.media.filter((item) => item.playerOwned).reduce((total, item) => total + item.revenue, 0)
103:   const corps = state.corporations.reduce((total, corp) => {
104:     const ownership = corp.playerShares / Math.max(1, corp.sharesOutstanding)
105:     return total + corp.revenue * 0.035 * ownership
106:   }, 0)
107:   const banks = state.banks.filter((bank) => bank.playerOwned).reduce((total, bank) => {
108:     return total + bank.loans * (bank.rate / 100) / 365
109:   }, 0)
110:   const property = state.districts.reduce((total, district) => total + district.owned * district.value * (district.yield / 100) / 365, 0)
111:   return isp + media + corps + banks + property
112: }
