122: export function tokenChange(token: Token, lookback = 12): number {
123:   if (token.history.length < 2) return 0
124:   const start = token.history[Math.max(0, token.history.length - 1 - lookback)]
125:   if (!start) return 0
126:   return ((token.price - start) / start) * 100
127: }
128: 
129: export function corpChange(corp: Corporation, lookback = 12): number {
130:   if (corp.history.length < 2) return 0
131:   const start = corp.history[Math.max(0, corp.history.length - 1 - lookback)]
132:   if (!start) return 0
133:   return ((corp.sharePrice - start) / start) * 100
134: }
135: 
136: export function marketCap(state: GameState): number {
137:   return state.tokens.reduce((total, token) => total + token.price * token.supply, 0)
138: }
