140: export function heatLabel(heat: number): { label: string; tone: 'good' | 'warn' | 'bad' } {
141:   if (heat >= 75) return { label: 'BURNING', tone: 'bad' }
142:   if (heat >= 50) return { label: 'HOT', tone: 'warn' }
143:   if (heat >= 25) return { label: 'WARM', tone: 'warn' }
144:   return { label: 'COOL', tone: 'good' }
145: }
